Variant Pedido
  Case Pendiente
  Case EnCamino(repartidor As String)
  Case Entregado(repartidor As String, hora As Integer)
  Case Cancelado(motivo As String)
EndVariant

Function texto <- Describir(pedido As Pedido)
  Define texto As String <- "";
  Switch pedido Do
    Pedido.Pendiente: texto <- "Pendiente";
    Pedido.EnCamino(quien): texto <- "En camino con " + quien;
    Pedido.Entregado(quien, hora): texto <- "Entregado por " + quien + " a las " + toText(hora);
    Pedido.Cancelado(motivo): texto <- "Cancelado: " + motivo;
  EndSwitch
EndFunction

Algorithm Envios
  Write Describir(Pedido.EnCamino("Sol"));
EndAlgorithm

Variant Pedido
  Case Pendiente
  Case EnCamino(repartidor As String)
  Case Entregado(repartidor As String, hora As Integer)
  Case Cancelado(motivo As String)
EndVariant

Function texto <- Describir(pedido As Pedido)
  Define texto As String <- "";
  Switch pedido Do
    Pedido.Pendiente: texto <- "Pendiente";
    Pedido.EnCamino(quien): texto <- "En camino con " + quien;
    Pedido.Entregado(quien, hora): texto <- "Entregado por " + quien + " a las " + toText(hora);
    Pedido.Cancelado(motivo): texto <- "Cancelado: " + motivo;
  EndSwitch
EndFunction

Subroutine Avanzar(pedido As Pedido, repartidor As String, hora As Integer) As Result<Pedido, String>
  Switch pedido Do
    Pedido.Pendiente: Return Success(Pedido.EnCamino(repartidor));
    Pedido.EnCamino(quien): Return Success(Pedido.Entregado(quien, hora));
    Pedido.Entregado(quien, cuando): Return Failure("ya lo entregó " + quien + " a las " + toText(cuando));
    Pedido.Cancelado(motivo): Return Failure("está cancelado: " + motivo);
  EndSwitch
EndSubroutine

Algorithm Envios
  Define pedido As Pedido <- Pedido.Pendiente;
  For paso <- 1 To 3 Do
    Write Describir(pedido);
    Switch Avanzar(pedido, "Sol", 14) Do
      Success(siguiente): pedido <- siguiente;
      Failure(motivo): Write "No se puede: ", motivo;
    EndSwitch
  EndFor
EndAlgorithm
